SELECT length('Lambda'), upper('Lambda'), lower('Lambda'), substr('Lambda', 0, 4), instr('Lambda', 'zeta'), replace('Lambda', 'e', '_'), trim('Lambda'), ltrim('Lambda', 'ab'), hex('Lambda'), quote('Lambda'), unicode('Lambda'), 'Lambda' LIKE '%é%', 'Lambda' GLOB '?', char(84, 863), 'Lambda' || 'zeta', 'Lambda' < 'zeta', 'Lambda' = 'zeta' COLLATE NOCASE;
SELECT length('chi'), upper('chi'), lower('chi'), substr('chi', 1, 4), instr('chi', 'iota'), replace('chi', '', 'XY'), trim('chi'), ltrim('chi', 'ab'), hex('chi'), quote('chi'), unicode('chi'), 'chi' LIKE '%a_', 'chi' GLOB 'a*', char(66, 476), 'chi' || 'iota', 'chi' < 'iota', 'chi' = 'iota' COLLATE NOCASE;
SELECT length('Ελλάδα'), upper('Ελλάδα'), lower('Ελλάδα'), substr('Ελλάδα', 1, 1), instr('Ελλάδα', 'NULL'), replace('Ελλάδα', '', ''), trim('Ελλάδα'), ltrim('Ελλάδα', 'ab'), hex('Ελλάδα'), quote('Ελλάδα'), unicode('Ελλάδα'), 'Ελλάδα' LIKE 'a%', 'Ελλάδα' GLOB 'a*', char(90, 348), 'Ελλάδα' || 'NULL', 'Ελλάδα' < 'NULL', 'Ελλάδα' = 'NULL' COLLATE NOCASE;
SELECT length('omega'), upper('omega'), lower('omega'), substr('omega', 1, 0), instr('omega', 'chi'), replace('omega', 'é', '_'), trim('omega'), ltrim('omega', 'ab'), hex('omega'), quote('omega'), unicode('omega'), 'omega' LIKE 'a%', 'omega' GLOB '?', char(75, 652), 'omega' || 'chi', 'omega' < 'chi', 'omega' = 'chi' COLLATE NOCASE;
SELECT length('chi'), upper('chi'), lower('chi'), substr('chi', 2, 1), instr('chi', 'zeta'), replace('chi', 'é', 'XY'), trim('chi'), ltrim('chi', 'ab'), hex('chi'), quote('chi'), unicode('chi'), 'chi' LIKE '%a_', 'chi' GLOB '*[a-m]*', char(80, 261), 'chi' || 'zeta', 'chi' < 'zeta', 'chi' = 'zeta' COLLATE NOCASE;
SELECT length('pi'), upper('pi'), lower('pi'), substr('pi', 3, 1), instr('pi', 'tau'), replace('pi', 'e', '_'), trim('pi'), ltrim('pi', 'ab'), hex('pi'), quote('pi'), unicode('pi'), 'pi' LIKE '%a_', 'pi' GLOB 'a*', char(76, 551), 'pi' || 'tau', 'pi' < 'tau', 'pi' = 'tau' COLLATE NOCASE;
SELECT a.id, b.id, a.c1, b.c1 FROM t0 a CROSS JOIN t1 b ORDER BY 1, 2 LIMIT 21;
SELECT count(*) FROM t0 a JOIN t0 b USING(id);
SELECT id, abs(CASE WHEN NULL THEN CASE WHEN -4 THEN c0 ELSE id END ELSE c0 BETWEEN 'Ελλάδα' AND -60 END), id FROM t0 ORDER BY id, c0, c1, c2 DESC;
SELECT -(NOT 5 IS NULL), -(x'ee57dc01e0');
SELECT count(*), count(c2), sum(c2), total(c2), avg(c2), min(c2), max(c2), count(DISTINCT c2) FROM t0 WHERE id;
SELECT c2, count(*), group_concat(id) FROM (SELECT * FROM t0 ORDER BY id) GROUP BY c2 ORDER BY c2;
